window.lvOn=k=>!!(LBC[k]&&LBC[k].vocab&&LBC[k].vocab.length);
window.lvBox=k=>{const id=idOf(k),g=build(k);if(!g)return '';if(VQ.u!==id||FC.u!==id){reset();FC.tab='cards'}
 const [i,l]=k.split('.').map(Number);
 return `<div id="lvBox" data-lvk="${k}"><h3 class="text-base font-bold">📚 Useful words from the lesson</h3><p class="mt-1 text-xs text-slate-500">${g.cards.length} từ / cụm từ của Lesson ${i+1}.${l+1}. Lật thẻ, học theo vòng, ghép thẻ rồi tự kiểm tra.</p><div id="lvIn">${inner(id)}</div></div>`};
document.addEventListener('click',e=>{const b=e.target.closest('[data-lvt]');if(!b)return;const box=document.getElementById('lvBox'),In=document.getElementById('lvIn');if(!box||!In)return;const k=box.dataset.lvk,id=idOf(k);try{fcStop();mtStop()}catch(_){}VQ.mt=null;FC.tab=b.dataset.lvt;build(k);In.innerHTML=inner(id)});
